mapper.select:
SELECT mc.id AS memberCouponId, mc.coupon_id AS couponId, mc.member_id AS memberId, c.name AS couponName, mc.issued_at AS issuedAt, c.starts_at AS startsAt, c.expires_at AS expiresAt FROM member_coupons mc INNER JOIN coupons c ON c.id = mc.coupon_id WHERE mc.status = 'AVAILABLE' AND c.status = 'ACTIVE' AND c.starts_at <= NOW(6) AND c.expires_at > NOW(6) AND c.target_type IN ('ALL_MEMBERS', 'NEW_MEMBERS', 'BIRTHDAY', 'SPECIFIC_MEMBERS')
AND mc.issued_at >= #{since}
AND ( mc.issued_at > #{lastIssuedAt} OR (mc.issued_at = #{lastIssuedAt} AND mc.id > #{lastMemberCouponId}) )
ORDER BY mc.issued_at ASC, mc.id ASC LIMIT #{limit}

SELECT mc.id AS memberCouponId, mc.coupon_id AS couponId, mc.member_id AS memberId, c.name AS couponName, mc.issued_at AS issuedAt, c.starts_at AS startsAt, c.expires_at AS expiresAt FROM coupons c INNER JOIN member_coupons mc ON mc.coupon_id = c.id WHERE c.status = 'ACTIVE' AND mc.status = 'AVAILABLE' AND c.starts_at <= NOW(6) AND c.expires_at > NOW(6) AND c.starts_at > mc.issued_at AND c.target_type IN ('ALL_MEMBERS', 'NEW_MEMBERS', 'BIRTHDAY', 'SPECIFIC_MEMBERS')
AND c.starts_at >= #{since}
AND ( c.starts_at > #{lastStartsAt} OR (c.starts_at = #{lastStartsAt} AND mc.id > #{lastMemberCouponId}) )
ORDER BY c.starts_at ASC, mc.id ASC LIMIT #{limit}

SELECT mc.id AS memberCouponId, mc.coupon_id AS couponId, mc.member_id AS memberId, c.name AS couponName, mc.issued_at AS issuedAt, c.starts_at AS startsAt, c.expires_at AS expiresAt FROM member_coupons mc INNER JOIN coupons c ON c.id = mc.coupon_id WHERE mc.status = 'AVAILABLE' AND c.status = 'ACTIVE' AND c.starts_at <= NOW(6) AND c.expires_at > NOW(6) AND c.expires_at <= DATE_ADD(NOW(6), INTERVAL #{days} DAY)
AND ( c.expires_at > #{lastExpiresAt} OR (c.expires_at = #{lastExpiresAt} AND mc.id > #{lastMemberCouponId}) )
ORDER BY c.expires_at ASC, mc.id ASC LIMIT #{limit}
